+      border: 1px solid rgba(148, 163, 184, 0.28);
+      border-radius: 18px;
+    }
+
+    .checkbox-row {
+      display: flex;
+      gap: 0.875rem;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      margin: 0.18rem 0 0;
+      inline-size: 1.15rem;
+      block-size: 1.15rem;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    label {
+      font-weight: 600;
+      line-height: 1.5;
+    }
+
+    .helper-text,
+    .error-text,
+    .status-message {
+      margin: 0;
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      color: var(--muted);
+    }
+
+    .error-text {
+      color: var(--danger);
+    }
+
+    .status-message {
+      min-height: 1.5rem;
+      color: var(--success-text);
+      font-weight: 600;
+    }
+
+    .status-message[data-state="success"] {
+      padding: 0.875rem 1rem;
+      background: var(--success-bg);
+      border-radius: 14px;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 0.9rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #fff;
+      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    :focus-visible {
+      outline: 3px solid #1d4ed8;
+      outline-offset: 3px;
+    }
+
+    input[aria-invalid="true"] + label {
+      color: #991b1b;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 1.5rem;
+        border-radius: 20px;
+      }
+    }
+
+    @media (prefers-reduced-motion: no-preference) {
+      .card,
+      button,
+      .skip-link {
+        transition: transform 0.2s ease, filter 0.2s ease, box-shadow 0.2s ease;
+      }
+
+      .card:hover {
+        transform: translateY(-2px);
+        box-shadow: 0 28px 64px rgba(15, 23, 42, 0.16);
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      .status-message[data-state="success"] {
+        border: 1px solid CanvasText;
+      }
+
+      button {
+        border: 1px solid ButtonText;
+      }
+    }
+  </style>
