  <title>Consent Form</title>
  <style>
    :root {
      color-scheme: light dark;
      --bg: #f4f7fb;
      --surface: rgba(255, 255, 255, 0.88);
      --surface-border: rgba(148, 163, 184, 0.28);
      --text: #0f172a;
      --muted: #475569;
      --accent: #4f46e5;
      --accent-strong: #4338ca;
      --danger: #b91c1c;
      --success-bg: #ecfdf5;
      --success-text: #166534;
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(99, 102, 241, 0.2), transparent 32%),
        linear-gradient(180deg, #eef2ff 0%, var(--bg) 42%, #e2e8f0 100%);
      color: var(--text);
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-220%);
      background: var(--text);
      color: #fff;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 30rem);
      background: var(--surface);
      backdrop-filter: blur(16px);
      border: 1px solid var(--surface-border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 2rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 1rem 0 1.5rem;
      color: var(--muted);
      line-height: 1.6;
    }

    .required-note {
      margin: 0 0 1.25rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.5rem;
      padding: 1rem;
      background: rgba(255, 255, 255, 0.72);
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 18px;
    }

    .checkbox-row {
      display: flex;
      gap: 0.875rem;
      align-items: flex-start;
    }

    input[type="checkbox"] {
      margin: 0.18rem 0 0;
      inline-size: 1.15rem;
      block-size: 1.15rem;
      accent-color: var(--accent);
      flex: none;
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .helper-text,
    .error-text,
    .status-message {
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--danger);
    }

    .status-message {
      min-height: 1.5rem;
      color: var(--success-text);
      font-weight: 600;
    }

    .status-message[data-state="success"] {
      padding: 0.875rem 1rem;
      background: var(--success-bg);
      border-radius: 14px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.05);
    }

    :focus-visible {
      outline: 3px solid #1d4ed8;
      outline-offset: 3px;
    }

    input[aria-invalid="true"] + label {
      color: #991b1b;
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.5rem;
        border-radius: 20px;
      }
    }

    @media (prefers-reduced-motion: no-preference) {
      .card,
      button,
      .skip-link {
        transition: transform 0.2s ease, filter 0.2s ease, box-shadow 0.2s ease;
      }

      .card:hover {
        transform: translateY(-2px);
        box-shadow: 0 28px 64px rgba(15, 23, 42, 0.16);
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      .status-message[data-state="success"] {
        border: 1px solid CanvasText;
      }

      button {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Account setup</p>
      <h1 id="page-title">Confirm your consent</h1>
      <p class="intro">Review the final step to continue with your account setup.</p>
      <p class="required-note">Required fields are marked with <span aria-hidden="true">*</span>.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="consent"
              name="consent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-error"
            >
            <label for="consent">I agree to the terms of use <span aria-hidden="true">*</span></label>
          </div>
          <p id="consent-help" class="helper-text">Required to continue with your submission.</p>
          <p id="consent-error" class="error-text" hidden>Error: Please agree to the terms of use before submitting.</p>
        </div>

        <button type="submit">Submit consent</button>
        <p id="form-status" class="status-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById("consent-form");
    const consent = document.getElementById("consent");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    function showError() {
      consent.setAttribute("aria-invalid", "true");
      error.hidden = false;
      status.textContent = "";
      status.removeAttribute("data-state");
    }

    function clearError() {
      consent.removeAttribute("aria-invalid");
      error.hidden = true;
    }

    consent.addEventListener("change", () => {
      if (consent.checked) {
        clearError();
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!consent.checked) {
        showError();
        consent.focus();
        return;
      }

      clearError();
      status.textContent = "Consent recorded. You're ready to continue.";
      status.setAttribute("data-state", "success");
    });
  </script>
</body>
</html>
